MAL=F('ASCARIS-MALE-REP-R1','Ascaris lumbricoides — male reproductive system','Male Ascaris reproductive tract showing single testis, vas deferens, seminal vesicle, ejaculatory duct, cloaca and copulatory spicules.',r'''<path d="M220 70C110 115 135 200 250 220C365 240 365 320 275 345" stroke-width="2.5"/><path d="M275 345Q340 365 410 345" stroke-width="3"/><ellipse cx="430" cy="345" rx="38" ry="22"/><path d="M468 345Q520 365 555 400" stroke-width="3"/><path d="M555 400l30 45m-20-45l10 50" stroke-width="2"/><g stroke-width="1"><path d="M220 70L60 60"/><path d="M220 210L60 210"/><path d="M430 345L650 300"/><path d="M520 375L650 375"/><path d="M575 445L650 445"/></g><g fill="#222" stroke="none" font-family="sans-serif" font-size="13"><text x="10" y="55">Single testis</text><text x="10" y="205">Vas deferens</text><text x="660" y="305">Seminal vesicle</text><text x="660" y="380">Ejaculatory duct → cloaca</text><text x="660" y="450">Copulatory spicules</text></g>''','Male: single testis → vas deferens → seminal vesicle → ejaculatory duct → cloaca; paired copulatory spicules associated with posterior cloacal region')
def repl_plate(s,old,new):
 p=rf'<figure[^>]*data-v188-plate="{re.escape(old)}"[\s\S]*?</figure>';o,n=re.subn(p,new,s,count=1)
 if n!=1:raise SystemExit(f'{old}: {n}')
 return o
def repl_ascaris(s):
 p=r'<figure class="sys-fig v188-pencil-plate">\s*<figcaption><strong>Ascaris lumbricoides — male and female reproductive systems</strong>[\s\S]*?</figure>'
 o,n=re.subn(p,FEM+MAL,s,count=1)
 if n!=1:raise SystemExit(f'Ascaris combined reproductive candidate: {n}')
 return o
def main(root):
 ps=[Path(root)/'academic_payload/index.html',Path(root)/'app/src/main/assets/www/index.html']
 for p in ps:
  s=p.read_text(encoding='utf-8');s=repl_plate(s,'master-fasciola-reproductive',FAS);s=repl_ascaris(s);p.write_text(s,encoding='utf-8')
 if ps[0].read_bytes()!=ps[1].read_bytes():raise SystemExit('payload copies diverged')
 print('Fasciola reproductive and sex-specific Ascaris reproductive FAIL rows remediated; BUILD_ELIGIBLE=NO')
if __name__=='__main__':main(sys.argv[1] if len(sys.argv)>1 else '.')